"""Garmin MCP generated by introspecting garminconnect.Garmin. No credentials here, tokens only.

Run `garmin_mcp.py smoke` for a pass/fail table over the enabled read tools.
"""
import datetime
import enum
import hashlib
import inspect
import json
import os
import random
import re
import sys
import threading
import time
import types
import typing
import zoneinfo

import garminconnect as gc
from garminconnect import Garmin

from stdio_mcp import serve

TOKENS = os.environ.get("GARMINTOKENS", "/garmin/tokens")
OUT_DIR = os.environ.get("GARMIN_OUTPUT_DIR", "/output")
UP_DIR = os.environ.get("GARMIN_UPLOAD_DIR", "/upload")
STATUS = os.environ.get("GARMIN_STATUS_FILE", "/tmp/garmin_status.json")
POLICY = os.environ.get("MCP_POLICY", "/policy/tools.json")
CACHE_S = int(os.environ.get("GARMIN_CACHE_SECONDS", "300"))
MIN_GAP = float(os.environ.get("GARMIN_MIN_INTERVAL", "1.5"))
MAX_HOUR = int(os.environ.get("GARMIN_MAX_PER_HOUR", "300"))
PAGE = int(os.environ.get("GARMIN_PAGE_CHARS", "40000"))
SMOKE_HOURS = float(os.environ.get("GARMIN_SMOKE_HOURS", "24"))

# raw escape hatches and session control never become tools
EXCLUDE = {"login", "logout", "resume_login", "connectapi", "connectwebproxy", "query_garmin_graphql",
           "download", "request_reload", "now", "today",
           # the library says these always raise (no such Garmin sport type)
           "upload_hiking_workout", "upload_walking_workout"}
DATE_RE = r"^\d{4}-\d{2}-\d{2}$"
lock = threading.Lock()
calls = []
cache = {}
client = None
state = {"auth": "unknown", "detail": ""}


# hand review of the prefix rules: moves a method to a stricter or more accurate class
OVERRIDE = {
    # settings, zones, activity uploads and menstrual data change or add things that are hard to undo
    **dict.fromkeys(["update_device_settings", "update_user_settings", "update_heart_rate_zones", "update_power_zones",
                     "update_menstrual_settings", "update_menstrual_calendar", "update_menstrual_daily_log",
                     "set_primary_training_device", "upload_activity", "import_activity", "create_manual_activity",
                     "create_manual_activity_from_json", "import_course", "confirm_menstrual_period_start",
                     "init_menstrual_cycle_setup"], "destructive"),
    **dict.fromkeys(["count_activities", "search_activities", "search_training_plans", "convert_activity_to_course"], "read"),
    **dict.fromkeys(["copy_workout", "move_calendar_item", "push_workout_to_device", "reschedule_workout",
                     "request_report", "send_scheduled_workouts_to_devices"], "write"),
    # reproductive health data: never enabled by class, only by name
    **dict.fromkeys(["get_menstrual_calendar_data", "get_menstrual_cycle_summary", "get_menstrual_data_for_date",
                     "get_menstrual_last_confirmed", "get_menstrual_reports", "get_pregnancy_summary"], "sensitive"),
}


def classify(n):
    if n in OVERRIDE:
        return OVERRIDE[n]
    if re.match(r"(delete|remove|unschedule)_", n):
        return "destructive"
    if re.match(r"(get|is|download)_", n):
        return "read"
    if re.match(r"(add|set|create|update|upload|schedule|import)_", n):
        return "write"
    return "unclassified"


def set_state(auth, detail=""):
    state.update(auth=auth, detail=detail)
    try:
        with open(STATUS, "w") as f:
            json.dump({**state, "ts": int(time.time())}, f)
    except OSError:
        pass


def jschema(tp):
    if tp is typing.Any or tp is inspect.Parameter.empty:
        return {}
    org, args = typing.get_origin(tp), typing.get_args(tp)
    if org in (typing.Union, types.UnionType):
        subs = [jschema(a) for a in args if a is not type(None)]
        return subs[0] if len(subs) == 1 else {"anyOf": subs}
    if org in (list, typing.List):
        return {"type": "array", "items": jschema(args[0]) if args else {}}
    if org in (dict, typing.Dict) or tp is dict:
        return {"type": "object"}
    if isinstance(tp, type) and issubclass(tp, enum.Enum):
        return {"type": "string", "enum": [m.name for m in tp]}
    if tp is bool:
        return {"type": "boolean"}
    if tp is int:
        return {"type": "integer"}
    if tp is float:
        return {"type": "number"}
    if tp in (str, datetime.date):
        return {"type": "string"}
    return {}


def coerce(tp, v):
    org, args = typing.get_origin(tp), typing.get_args(tp)
    if v is None:
        return None
    if org in (typing.Union, types.UnionType):
        for a in args:
            if a is type(None):
                continue
            try:
                return coerce(a, v)
            except (ValueError, TypeError, KeyError):
                continue
        raise ValueError("no matching type")
    if isinstance(tp, type) and issubclass(tp, enum.Enum):
        return tp[str(v).upper()]
    if tp is bool:
        if not isinstance(v, bool):
            raise ValueError("expected boolean")
        return v
    if tp is int:
        if isinstance(v, bool) or not re.fullmatch(r"-?\d+", str(v)):
            raise ValueError("expected integer")
        return int(v)
    if tp is float:
        return float(v)
    if tp is str:
        return v if isinstance(v, str) else str(v)
    if tp is datetime.date:
        return datetime.date.fromisoformat(v)
    return v


def inside(base, p):
    real = os.path.realpath(p)
    root = os.path.realpath(base)
    if not (real == root or real.startswith(root + os.sep)):
        raise ValueError(f"path must be inside {base}")
    return real


def build_tools():
    out = {}
    for n, m in inspect.getmembers(Garmin, inspect.isfunction):
        if n.startswith("_") or n in EXCLUDE:
            continue
        try:
            hints = typing.get_type_hints(m)
        except Exception:
            hints = {}
        sig = inspect.signature(m)
        props, req, params = {}, [], {}
        for p in list(sig.parameters.values())[1:]:
            if p.kind in (p.VAR_POSITIONAL, p.VAR_KEYWORD):
                continue
            tp = hints.get(p.name, p.annotation)
            s = jschema(tp)
            if re.search(r"date", p.name) and s.get("type") == "string":
                s["pattern"] = DATE_RE
                s["description"] = "YYYY-MM-DD"
            if p.default is inspect.Parameter.empty:
                req.append(p.name)
            elif isinstance(p.default, (str, int, float, bool)):
                s["default"] = p.default
            props[p.name], params[p.name] = s, (tp, p)
        cls = classify(n)
        if cls in ("read", "sensitive"):
            props["_page"] = {"type": "integer", "description": "0-based page of a large result"}
        doc = (inspect.getdoc(m) or n).split("\n\n")[0].replace("\n", " ")
        if cls == "destructive":
            doc += " DESTRUCTIVE: requires explicit user confirmation."
        out[n] = dict(desc=f"[{cls}] {doc}"[:900],
                      schema={"type": "object", "properties": props, "required": req, "additionalProperties": False},
                      fn=make_call(n, params, cls), ro=cls in ("read", "sensitive"), cls=cls)
    return out


def wait_turn():
    now = time.time()
    calls[:] = [t for t in calls if t > now - 3600]
    if len(calls) >= MAX_HOUR:
        raise RuntimeError("rate limited, retry later (hourly cap reached)")
    if calls and now - calls[-1] < MIN_GAP:
        time.sleep(MIN_GAP - (now - calls[-1]))
    calls.append(time.time())


def get_client():
    global client
    if client is None:
        c = Garmin()
        c.login(TOKENS)
        client = c
    return client


def save_bytes(name, data):
    os.makedirs(OUT_DIR, mode=0o700, exist_ok=True)
    ext = "zip" if data[:2] == b"PK" else "fit" if data[8:12] == b".FIT" else "xml" if data[:5] in (b"<?xml", b"<gpx ") else "bin"
    path = os.path.join(OUT_DIR, f"{name}-{int(time.time())}-{hashlib.sha256(data).hexdigest()[:8]}.{ext}")
    with open(path, "wb") as f:
        f.write(data)
    return {"saved_to": path, "bytes": len(data), "type": ext}


def make_call(name, params, cls):
    def fn(a):
        a = dict(a)
        page = a.pop("_page", 0) if cls in ("read", "sensitive") else 0
        unknown = set(a) - set(params)
        if unknown:
            raise RuntimeError(f"unknown arguments: {sorted(unknown)}")
        kw = {}
        for k, v in a.items():
            tp, _ = params[k]
            try:
                if re.search(r"path|file", k) and isinstance(v, str):
                    v = inside(UP_DIR, v)
                if k == "workout" and name.startswith("upload_") and isinstance(v, dict):
                    model = getattr(gc.workout, name[7:-8].title().replace("_", "") + "Workout", None)
                    v = model.model_validate(v) if model else v
                kw[k] = coerce(tp, v)
            except (ValueError, TypeError, KeyError) as e:
                raise RuntimeError(f"bad value for {k}: {e}")
        missing = [k for k, (_, p) in params.items() if p.default is inspect.Parameter.empty and k not in kw]
        if missing:
            raise RuntimeError(f"missing arguments: {missing}")
        key = (name, json.dumps(kw, sort_keys=True, default=str))
        hit = cache.get(key) if cls in ("read", "sensitive") else None
        if hit and time.time() - hit[0] < CACHE_S:
            res = hit[1]
        else:
            res = invoke(name, kw)
            if cls in ("read", "sensitive"):
                cache[key] = (time.time(), res)
        if isinstance(res, (bytes, bytearray)):
            return save_bytes(name, bytes(res))
        text = json.dumps(res, ensure_ascii=False, default=str)
        if len(text) <= PAGE:
            return text
        pages = -(-len(text) // PAGE)
        return json.dumps({"page": page, "pages": pages, "text": text[page * PAGE:(page + 1) * PAGE]})
    return fn


def invoke(name, kw):
    if state["auth"] == "reauth":
        raise RuntimeError("re-authentication needed: run the interactive garmin login on the Pi")
    with lock:
        for attempt in range(4):
            try:
                wait_turn()
                res = getattr(get_client(), name)(**kw)
                set_state("ok")
                return res
            except gc.GarminConnectAuthenticationError as e:
                set_state("reauth", type(e).__name__)
                raise RuntimeError("re-authentication needed: run the interactive garmin login on the Pi")
            except gc.GarminConnectTooManyRequestsError:
                if attempt == 3:
                    raise RuntimeError("rate limited, retry later")
                time.sleep(2 ** (attempt + 1) + random.random() * 2)
            except gc.GarminConnectConnectionError as e:
                # a failing request is retried once, never four times: Garmin's private API should not be hammered
                if attempt >= 1:
                    raise RuntimeError(f"Garmin refused or failed the request: {str(e)[:100]}")
                time.sleep(2 + random.random() * 2)
            except (gc.GarminConnectNotFoundError, gc.GarminConnectInvalidFileFormatError) as e:
                raise RuntimeError(type(e).__name__)
    raise RuntimeError("unreachable")


def enabled_reads(tools):
    try:
        with open(POLICY) as f:
            pol = json.load(f)
    except (OSError, ValueError):
        pol = {}
    classes = (pol.get("classes") or {}).get("garmin", [])
    off, on = set(pol.get("disabled", [])), set(pol.get("enable", []))
    return [n for n, t in tools.items() if t["cls"] == "read" and n not in off and (n in on or "read" in classes)]


# the account answers 400 to every call of these (no matching device or capability), so the smoke test reports them apart
KNOWN_UNSUPPORTED = {"get_ecg_list": "400 for every argument, probably no ECG device"}


def smoke(tools):
    today = datetime.datetime.now(zoneinfo.ZoneInfo("Europe/Warsaw")).date().isoformat()  # the container runs in UTC
    rows = []
    for n in enabled_reads(tools):
        props = tools[n]["schema"]["properties"]
        req = tools[n]["schema"]["required"]
        args = {}
        for r in req:
            if re.search(r"date", r):
                args[r] = today
            else:
                args = None
                break
        if n in KNOWN_UNSUPPORTED:
            rows.append((n, "skip", KNOWN_UNSUPPORTED[n]))
            continue
        if args is not None and "days" in props:  # Garmin rejects the library default of 7 days with a 400
            args["days"] = 3
        if args is not None:  # optional range ends make some endpoints refuse their defaults
            if "end" in props:
                args["end"] = today
            if "start" in props and "end" in props:
                args["start"] = (datetime.date.fromisoformat(today) - datetime.timedelta(days=6)).isoformat()
        if args is None:
            rows.append((n, "skip", "needs an id"))
            continue
        try:
            tools[n]["fn"]({**args, "_page": 0})
            rows.append((n, "pass", ""))
        except Exception as e:
            rows.append((n, "FAIL", str(e)[:80]))
            if state["auth"] == "reauth":
                break
        time.sleep(3)
    return rows


def smoke_loop(tools):
    time.sleep(120)
    while True:
        rows = smoke(tools)
        bad = [r[0] for r in rows if r[1] == "FAIL"]
        with open("/tmp/garmin_smoke.json", "w") as f:
            json.dump({"ts": int(time.time()), "pass": sum(r[1] == "pass" for r in rows), "fail": bad}, f)
        time.sleep(SMOKE_HOURS * 3600)


if __name__ == "__main__":
    tools = build_tools()
    if len(sys.argv) > 1 and sys.argv[1] == "classes":
        print(json.dumps({n: t["cls"] for n, t in tools.items()}, indent=1))
    elif len(sys.argv) > 1 and sys.argv[1] == "smoke":
        for n, s, d in smoke(tools):
            print(f"{s:5} {n} {d}")
        sys.exit(1 if state["auth"] == "reauth" else 0)
    else:
        try:
            get_client()
            set_state("ok")
        except Exception as e:
            set_state("reauth", type(e).__name__)
        if SMOKE_HOURS > 0:
            threading.Thread(target=smoke_loop, args=(tools,), daemon=True).start()
        serve("garmin", {n: {**t, "class": t["cls"]} for n, t in tools.items()})
